css:
/* Plakátové nadpisy */
h1, h2, h3, .mb-brand { text-transform: uppercase; letter-spacing: 0.02em; }
/* Karty jako vystřižené z papíru */
.card, .mb-panel { border: 2px solid var(--color-white); }
.btn { border: 2px solid var(--color-white); }
/* Jednoduše: zvýraznění v červené z trikolóry, bez barevné záře */
.mb-accent-scope { --mb-accent: var(--color-pink) !important; }
.mb-glow { display: none !important; }
